# Let's read the syslog file and extract lines with 'error', 'failed', 'fail', 'lvm', 'parted', 'mkfs', 'mount'
import re

errors = []
with open('/mnt/data/syslog', errors='ignore') as f:
    for line in f:
        if re.search(r'error|failed|fail|lvm|parted|mkfs|mount|mdadm|vgcreate|pvcreate|lvcreate', line, re.IGNORECASE):
            errors.append(line.strip())
# Print the last 50 error-like lines
for ln in errors[-50:]:
    print(ln)

